        for (final j in jobs.entries) {
          final steps = (j.value as YamlMap)['steps'] as YamlList?;
          if (steps == null) continue;
          for (final s in steps.whereType<YamlMap>()) {
            if ((s['name']?.toString() ?? '') == entry.value) {
