            script,
            contains('git clone --reference'),
            reason: 'the local-mirror clone shape is kept (gh-1600, $entry.key)',
          );
          expect(
            RegExp(r'^\s*rm -rf "\$GITHUB_WORKSPACE"\s*$', multiLine: true)
                .hasMatch(script),
