python3 - <<'EOF'
import yaml, subprocess, sys
for wf in ['.github/workflows/bench-harbor.yml', '.github/workflows/build-mobile.yml', '.github/workflows/build-macos.yml']:
    doc = yaml.safe_load(open(wf))
    n = 0
    for job, jdef in doc['jobs'].items():
        for step in jdef.get('steps', []):
            if isinstance(step, dict) and 'run' in step:
                script = step['run']
                if 'GITHUB_WORKSPACE' in script or 'docker' in script or 'harbor' in script:
                    p = subprocess.run(['bash', '-n'], input=script, text=True, capture_output=True)
                    if p.returncode != 0:
                        print(f'FAIL {wf}::{job}::{step.get("name")}: {p.stderr}')
                        sys.exit(1)
                    n += 1
    print(f'{wf}: {n} embedded script(s) bash -n clean')
EOF

